 "content": "def transform(grid):
    """Complete the rectangular perimeter around the sparse marker set in color 2."""
    h, w = len(grid), len(grid[0])
    counts = {}
    positions = {}
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            counts[value] = counts.get(value, 0) + 1
            positions.setdefault(value, []).append((r, c))
    background = max(counts, key=counts.get)
    marker_colors = [color for color in counts if color != background]
    if not marker_colors:
        return [row[:] for row in grid]
    marker = max(marker_colors, key=lambda color: counts[color])
    points = positions[marker]
    min_r = min(r for r, _ in points)
    max_r = max(r for r, _ in points)
    min_c = min(c for _, c in points)
    max_c = max(c for _, c in points)
    out = [row[:] for row in grid]
    for r in range(min_r, max_r + 1):
        for c in range(min_c, max_c + 1):
            if r in (min_r, max_r) or c in (min_c, max_c):
                if grid[r][c] == background:
                    out[r][c] = 2
    return out

if __name__ == '__main__':
    import json
    test = [[9,9,9,9,9,9,9,9],[9,9,9,9,9,9,9,9],[9,9,1,9,1,9,1,9],[9,9,9,9,9,9,1,9],[9,9,1,9,9,9,1,9],[9,9,1,9,9,9,1,9],[9,9,1,9,9,9,1,9],[9,9,1,9,9,9,1,9],[9,9,9,9,9,9,1,9],[9,9,9,9,9,9,9,9],[9,9,1,9,9,9,1,9],[9,9,1,9,9,9,1,9],[9,9,9,9,9,9,9,9],[9,9,1,9,9,1,1,9],[9,9,9,9,9,9,9,9],[9,9,9,9,9,9,9,9],[9,9,9,9,9,9,9,9]]
    result = transform(test)
    assert len(result) == 17 and all(len(row) == 8 for row in result)
    assert all(type(v) is int and 0 <= v <= 9 for row in result for v in row)
    print(json.dumps(result, separators=(',', ':')))
    print('dimensions/palette valid')
